using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using Staybnb.Data; using Staybnb.Models; using Staybnb.Services;
namespace Staybnb.Controllers;
[Authorize(Roles="Guest,Host")]
public class HostApplicationsController(ApplicationDbContext db,UserManager<ApplicationUser> users,ActivityLogger logger,IWebHostEnvironment env):Controller {
 [HttpGet] [Authorize(Roles="Guest")] public IActionResult Apply()=>View(new HostApplicationViewModel());
 [HttpPost,ValidateAntiForgeryToken,Authorize(Roles="Guest")] public async Task<IActionResult> Apply(HostApplicationViewModel model){if(model.Images==null||model.Images.Count==0)ModelState.AddModelError(nameof(model.Images),"Upload at least one property image before submitting.");if(model.Images?.Any(f=>f.Length>5*1024*1024)==true)ModelState.AddModelError(nameof(model.Images),"Each image must be 5 MB or smaller.");if(!ModelState.IsValid)return View(model);var uid=users.GetUserId(User)!;if(await db.HostApplications.AnyAsync(a=>a.ApplicantId==uid&&a.Status=="Pending")){ModelState.AddModelError("","You already have a pending application.");return View(model);}var p=new Property{Title=model.Title,Description=model.Description,PricePerNight=model.PricePerNight,CleaningFee=model.CleaningFee,ServiceFee=model.ServiceFee,Address=model.Address,City=model.City,PropertyType=model.PropertyType,MaxGuests=model.MaxGuests,HostId=uid,IsActive=false};db.Properties.Add(p);await db.SaveChangesAsync();var folder=Path.Combine(env.WebRootPath,"uploads");Directory.CreateDirectory(folder);int i=0;foreach(var file in model.Images){if(file.Length==0)continue;var ext=Path.GetExtension(file.FileName).ToLowerInvariant();if(!new[]{".jpg",".jpeg",".png",".webp"}.Contains(ext))continue;var name=$"{Guid.NewGuid():N}{ext}";await using var stream=System.IO.File.Create(Path.Combine(folder,name));await file.CopyToAsync(stream);db.PropertyImages.Add(new PropertyImage{PropertyId=p.Id,ImagePath="/uploads/"+name,IsPrimary=i++==0});}if(i==0){db.Properties.Remove(p);await db.SaveChangesAsync();ModelState.AddModelError(nameof(model.Images),"Upload at least one valid JPG, PNG or WEBP image.");return View(model);}db.HostApplications.Add(new HostApplication{ApplicantId=uid,PropertyId=p.Id});await db.SaveChangesAsync();await logger.LogAsync(uid,"HostApplicationSubmitted",$"Host application #{p.Id} submitted with images.","HostApplication",p.Id.ToString());TempData["Message"]="Application submitted for review.";return RedirectToAction(nameof(MyApplications));}
 [HttpGet,Authorize(Roles="Guest,Host")] public async Task<IActionResult> MyApplications(){var uid=users.GetUserId(User);return View(await db.HostApplications.Include(a=>a.Property).Where(a=>a.ApplicantId==uid).OrderByDescending(a=>a.SubmittedAt).ToListAsync());}
 [Authorize(Roles="Host")] public async Task<IActionResult> CheckInSettings(int propertyId){var uid=users.GetUserId(User);var property=await db.Properties.FirstOrDefaultAsync(p=>p.Id==propertyId&&p.HostId==uid);if(property==null)return NotFound();ViewBag.Property=property;return View(await db.CheckInProcesses.FirstOrDefaultAsync(c=>c.PropertyId==propertyId)??new CheckInProcess{PropertyId=propertyId});}
 [HttpPost,ValidateAntiForgeryToken,Authorize(Roles="Host")] public async Task<IActionResult> CheckInSettings(CheckInProcess model){var uid=users.GetUserId(User);var property=await db.Properties.FirstOrDefaultAsync(p=>p.Id==model.PropertyId&&p.HostId==uid);if(property==null)return NotFound();if(!ModelState.IsValid){ViewBag.Property=property;return View(model);}var existing=await db.CheckInProcesses.FirstOrDefaultAsync(c=>c.PropertyId==model.PropertyId);if(existing==null){model.Property=property;model.UpdatedAt=DateTime.UtcNow;db.CheckInProcesses.Add(model);}else{existing.Instructions=model.Instructions;existing.RequiredDocuments=model.RequiredDocuments;existing.UpdatedAt=DateTime.UtcNow;}await db.SaveChangesAsync();await logger.LogAsync(uid,"CheckInProcessUpdated",$"Check-in instructions updated for property #{property.Id}.","Property",property.Id.ToString());TempData["Message"]="Check-in instructions saved.";return RedirectToAction(nameof(CheckInSettings),new{propertyId=property.Id});}
 [Authorize(Roles="Host")] public async Task<IActionResult> ViewGuestDocument(int id){var uid=users.GetUserId(User);var d=await db.GuestDocuments.Include(x=>x.Booking).ThenInclude(b=>b!.Property).FirstOrDefaultAsync(x=>x.Id==id&&x.Booking!.Property!.HostId==uid);if(d==null)return NotFound();var path=Path.Combine(env.ContentRootPath,"PrivateUploads",d.FilePath);if(!System.IO.File.Exists(path))return NotFound();var ext=Path.GetExtension(path).ToLowerInvariant();var contentType=ext==".pdf"?"application/pdf":ext==".png"?"image/png":"image/jpeg";return PhysicalFile(path,contentType,enableRangeProcessing:true);}
 [Authorize(Roles="Host")] public async Task<IActionResult> GuestDocuments(){var uid=users.GetUserId(User);return View(await db.GuestDocuments.Include(d=>d.Booking).ThenInclude(b=>b!.Property).Include(d=>d.Booking).ThenInclude(b=>b!.Guest).Where(d=>d.Booking!.Property!.HostId==uid).OrderByDescending(d=>d.UploadedAt).ToListAsync());}
 [HttpPost,ValidateAntiForgeryToken,Authorize(Roles="Host")] public async Task<IActionResult> VerifyGuestDocument(int id,string decision){if(decision is not("Verified" or "Rejected"))return BadRequest();var uid=users.GetUserId(User);var d=await db.GuestDocuments.Include(x=>x.Booking).ThenInclude(b=>b!.Property).FirstOrDefaultAsync(x=>x.Id==id&&x.Booking!.Property!.HostId==uid);if(d==null)return NotFound();d.Status=decision;d.ReviewedAt=DateTime.UtcNow;await db.SaveChangesAsync();await logger.LogAsync(uid,"DocumentReviewed",$"Document #{id} marked {decision}.","GuestDocument",id.ToString());return RedirectToAction(nameof(GuestDocuments));}
 [Authorize(Roles="Host")] public async Task<IActionResult> Dashboard(){var uid=users.GetUserId(User);ViewBag.Properties=await db.Properties.Include(p=>p.Images).Where(p=>p.HostId==uid).ToListAsync();ViewBag.Bookings=await db.Bookings.Include(b=>b.Property).Include(b=>b.Guest).Where(b=>b.Property!.HostId==uid).OrderByDescending(b=>b.CreatedAt).ToListAsync();return View();}
}